        public static Geometry Get(string name)
        {
            Geometry g;
            if (Cache.TryGetValue(name, out g)) return g;
            string d;
            if (!Paths.TryGetValue(name, out d)) d = Paths["settings"];
            g = Geometry.Parse(d);
            g.Freeze();
            Cache[name] = g;
            return g;
        }

        public static bool Has(string name)
        {
            return Paths.ContainsKey(name);
        }
